<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ChevronLeft,ChevronRight}from'@lucide/vue';import StatusBadge from'../components/StatusBadge.vue';import{useInstrumentStore}from'../stores/instruments';const store=useInstrumentStore();const cursor=ref(new Date());onMounted(store.load);const title=computed(()=>cursor.value.toLocaleDateString('zh-CN',{year:'numeric',month:'long'}));const days=computed(()=>{const year=cursor.value.getFullYear(),month=cursor.value.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),result:(Date|null)[]=Array(first.getDay()).fill(null);for(let d=1;d<=last.getDate();d++)result.push(new Date(year,month,d));return result});function shift(delta:number){cursor.value=new Date(cursor.value.getFullYear(),cursor.value.getMonth()+delta,1)}function due(day:Date|null){if(!day)return[];return store.instruments.filter(item=>{const value=new Date(item.next_due_at);return value.toDateString()===day.toDateString()})}</script><template><section><div class="page-title"><div><h1>校准日历</h1><p>按到期日统筹计划任务与逾期风险</p></div><div class="month-switch"><button class="icon" title="上个月" @click="shift(-1)"><ChevronLeft/></button><strong>{{title}}</strong><button class="icon" title="下个月" @click="shift(1)"><ChevronRight/></button></div></div><div class="calendar"><div v-for="label in ['日','一','二','三','四','五','六']" :key="label" class="weekday">{{label}}</div><div v-for="(day,index) in days" :key="index" class="calendar-day" :class="{muted:!day}"><span v-if="day">{{day.getDate()}}</span><div v-for="item in due(day)" :key="item.id" class="calendar-item"><strong>{{item.asset_number}}</strong><StatusBadge :status="item.status"/></div></div></div></section></template>

